import fs from 'node:fs';
const scaffoldTemplate = (name) =>
  fs
    .readFileSync(new URL('../../assets/scaffold/' + name, import.meta.url), 'utf8')
    .replace(/\r\n/g, '\n');

const PKG = 'com.example.demo';

function pkgOf(context) {
  return String(context.packageName || PKG);
}

function pkgPath(context) {
  return pkgOf(context).replace(/\./g, '/');
}

function lines(...rows) {
  return rows.join('\n') + '\n';
}

function javaFiles(context) {
  const pkg = pkgOf(context);
  const dir = 'src/main/java/' + pkgPath(context);
  const testDir = 'src/test/java/' + pkgPath(context);
  const validation = String(context.bootVersion || '2.7.x').startsWith('2')
    ? 'javax.validation'
    : 'jakarta.validation';
  const files = {};
  files[dir + '/Item.java'] = lines(
    'package ' + pkg + ';',
    '',
    '/** Item resource. */',
    'public class Item {',
    '  private long id;',
    '  private String name;',
    '  private String description;',
    '',
    '  /** Creates an empty item. */',
    '  public Item() {}',
    '',
    '  /** Creates an item. */',
    '  public Item(long id, String name, String description) {',
    '    this.id = id;',
    '    this.name = name;',
    '    this.description = description;',
    '  }',
    '',
    '  /** Returns the id. */',
    '  public long getId() { return id; }',
    '',
    '  /** Sets the id. */',
    '  public void setId(long id) { this.id = id; }',
    '',
    '  /** Returns the name. */',
    '  public String getName() { return name; }',
    '',
    '  /** Sets the name. */',
    '  public void setName(String name) { this.name = name; }',
    '',
    '  /** Returns the description. */',
    '  public String getDescription() { return description; }',
    '',
    '  /** Sets the description. */',
    '  public void setDescription(String description) { this.description = description; }',
    '}',
  );
  files[dir + '/ItemStore.java'] = lines(
    'package ' + pkg + ';',
    '',
    'import java.util.ArrayList;',
    'import java.util.List;',
    'import java.util.Map;',
    'import java.util.Optional;',
    'import java.util.concurrent.ConcurrentHashMap;',
    'import java.util.concurrent.atomic.AtomicLong;',
    'import org.springframework.stereotype.Component;',
    '',
    '/** In-memory item store. */',
    '@Component',
    'public class ItemStore {',
    '  private final AtomicLong sequence = new AtomicLong();',
    '  private final Map<Long, Item> items = new ConcurrentHashMap<>();',
    '',
    '  /** Lists all items. */',
    '  public List<Item> list() { return new ArrayList<>(items.values()); }',
    '',
    '  /** Finds an item by id. */',
    '  public Optional<Item> get(long id) { return Optional.ofNullable(items.get(id)); }',
    '',
    '  /** Creates an item. */',
    '  public Item create(String name, String description) {',
    '    long id = sequence.incrementAndGet();',
    '    Item item = new Item(id, name, description);',
    '    items.put(id, item);',
    '    return item;',
    '  }',
    '',
    '  /** Updates an item. */',
    '  public Optional<Item> update(long id, String name, String description) {',
    '    if (!items.containsKey(id)) {',
    '      return Optional.empty();',
    '    }',
    '    Item item = new Item(id, name, description);',
    '    items.put(id, item);',
    '    return Optional.of(item);',
    '  }',
    '',
    '  /** Deletes an item. */',
    '  public boolean delete(long id) { return items.remove(id) != null; }',
    '',
    '  /** Clears all items for tests. */',
    '  public void clear() {',
    '    items.clear();',
    '    sequence.set(0);',
    '  }',
    '}',
  );
  files[dir + '/ItemController.java'] = scaffoldTemplate('java/ItemController.java')
    .replaceAll('__PACKAGE__', pkg)
    .replaceAll('__VALIDATION__', validation);
  files[testDir + '/ItemControllerTest.java'] = scaffoldTemplate(
    'java/ItemControllerTest.java',
  ).replaceAll('__PACKAGE__', pkg);
  return files;
}

function nodeFiles() {
  return {
    'src/items.js': scaffoldTemplate('node/items.js'),
    'index.js': lines(
      'import http from "node:http";',
      'import { pathToFileURL } from "node:url";',
      'import { handleItems } from "./src/items.js";',
      '',
      'export function createApp() {',
      '  return http.createServer(async (req, res) => {',
      '    const url = new URL(req.url, "http://localhost");',
      '    if (req.method === "GET" && url.pathname === "/health") {',
      '      res.writeHead(200, { "content-type": "application/json" });',
      '      res.end(JSON.stringify({ status: "ok" }));',
      '      return;',
      '    }',
      '    if (await handleItems(req, res)) return;',
      '    res.writeHead(404, { "content-type": "application/json" });',
      '    res.end(JSON.stringify({ error: "not found" }));',
      '  });',
      '}',
      '',
      'if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {',
      '  createApp().listen(3000, () => console.log("listening on 3000"));',
      '}',
    ),
    'test/items.test.mjs': lines(
      'import test from "node:test";',
      'import assert from "node:assert/strict";',
      'import { createApp } from "../index.js";',
      'import { resetItems } from "../src/items.js";',
      '',
      'async function withServer(fn) {',
      '  resetItems();',
      '  const server = createApp().listen(0);',
      '  const port = server.address().port;',
      '  try { await fn("http://127.0.0.1:" + port); } finally { server.close(); }',
      '}',
      '',
      'test("AC-001 list returns array", async () => {',
      '  await withServer(async (base) => {',
      '    const res = await fetch(base + "/api/items");',
      '    assert.equal(res.status, 200);',
      '    assert.deepEqual(await res.json(), []);',
      '  });',
      '});',
      '',
      'test("AC-002/AC-004 create then get", async () => {',
      '  await withServer(async (base) => {',
      '    const created = await fetch(base + "/api/items", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "demo" }) });',
      '    assert.equal(created.status, 201);',
      '    const item = await created.json();',
      '    assert.equal(item.id, 1);',
      '    const res = await fetch(base + "/api/items/1");',
      '    assert.equal(res.status, 200);',
      '    assert.equal((await res.json()).name, "demo");',
      '  });',
      '});',
      '',
      'test("AC-003 get missing returns 404", async () => {',
      '  await withServer(async (base) => {',
      '    assert.equal((await fetch(base + "/api/items/999")).status, 404);',
      '  });',
      '});',
      '',
      'test("AC-005 create without name returns 400", async () => {',
      '  await withServer(async (base) => {',
      '    const res = await fetch(base + "/api/items", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({}) });',
      '    assert.equal(res.status, 400);',
      '  });',
      '});',
      '',
      'test("AC-006 update item", async () => {',
      '  await withServer(async (base) => {',
      '    await fetch(base + "/api/items", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "demo" }) });',
      '    const res = await fetch(base + "/api/items/update", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: 1, name: "updated" }) });',
      '    assert.equal(res.status, 200);',
      '    assert.equal((await res.json()).name, "updated");',
      '  });',
      '});',
      '',
      'test("AC-007 update missing returns 404", async () => {',
      '  await withServer(async (base) => {',
      '    const res = await fetch(base + "/api/items/update", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: 999, name: "x" }) });',
      '    assert.equal(res.status, 404);',
      '  });',
      '});',
      '',
      'test("AC-008/AC-009 delete item and missing", async () => {',
      '  await withServer(async (base) => {',
      '    await fetch(base + "/api/items", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "demo" }) });',
      '    assert.equal((await fetch(base + "/api/items/delete", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: 1 }) })).status, 200);',
      '    assert.equal((await fetch(base + "/api/items/1")).status, 404);',
      '    assert.equal((await fetch(base + "/api/items/delete", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: 999 }) })).status, 404);',
      '  });',
      '});',
    ),
  };
}

function pythonFiles() {
  return {
    'items.py': scaffoldTemplate('python/items.py'),
    'app.py': lines(
      'import json',
      'from http.server import BaseHTTPRequestHandler, HTTPServer',
      '',
      'from items import handle_items',
      '',
      '',
      'class Handler(BaseHTTPRequestHandler):',
      '    def send_error(self, code, message=None, explain=None):',
      '        self._send(code, {"error": "request failed"})',
      '',
      '    def _send(self, status, payload=None):',
      '        body = b"" if payload is None else json.dumps(payload).encode("utf-8")',
      '        self.send_response(status)',
      '        self.send_header("content-type", "application/json")',
      '        self.send_header("content-length", str(len(body)))',
      '        self.end_headers()',
      '        if body:',
      '            self.wfile.write(body)',
      '',
      '    def _dispatch(self):',
      '        if handle_items(self):',
      '            return',
      '        if self.command == "GET" and self.path == "/health":',
      '            self._send(200, {"status": "ok"})',
      '            return',
      '        self._send(404, {"error": "not found"})',
      '',
      '    def do_GET(self):',
      '        self._dispatch()',
      '',
      '    def do_POST(self):',
      '        self._dispatch()',
      '',
      '    def do_PUT(self):',
      '        self._dispatch()',
      '',
      '    def do_DELETE(self):',
      '        self._dispatch()',
      '',
      '    def log_message(self, format, *args):',
      '        return',
      '',
      '',
      'def serve(port=8000):',
      '    HTTPServer(("127.0.0.1", port), Handler).serve_forever()',
      '',
      '',
      'if __name__ == "__main__":',
      '    serve()',
    ),
    'tests/test_items.py': lines(
      'import json',
      'import threading',
      'import urllib.error',
      'import urllib.request',
      'from http.server import HTTPServer',
      '',
      'import pytest',
      '',
      'import app as app_module',
      'from items import STORE',
      '',
      '',
      '@pytest.fixture()',
      'def base_url():',
      '    STORE.clear()',
      '    server = HTTPServer(("127.0.0.1", 0), app_module.Handler)',
      '    thread = threading.Thread(target=server.serve_forever, daemon=True)',
      '    thread.start()',
      '    try:',
      '        yield "http://127.0.0.1:%d" % server.server_port',
      '    finally:',
      '        server.shutdown()',
      '        server.server_close()',
      '',
      '',
      'def request(base, path, method="GET", body=None):',
      '    data = None if body is None else json.dumps(body).encode("utf-8")',
      '    req = urllib.request.Request(base + path, data=data, method=method)',
      '    if data is not None:',
      '        req.add_header("content-type", "application/json")',
      '    try:',
      '        with urllib.request.urlopen(req) as response:',
      '            raw = response.read().decode("utf-8")',
      '            return response.status, json.loads(raw) if raw else None',
      '    except urllib.error.HTTPError as error:',
      '        raw = error.read().decode("utf-8")',
      '        return error.code, json.loads(raw) if raw else None',
      '',
      '',
      'def test_list_empty(base_url):',
      '    assert request(base_url, "/api/items") == (200, [])',
      '',
      '',
      'def test_create_and_get(base_url):',
      '    status, item = request(base_url, "/api/items", "POST", {"name": "demo"})',
      '    assert status == 201',
      '    assert item["id"] == 1',
      '    assert request(base_url, "/api/items/1")[0] == 200',
      '',
      '',
      'def test_get_missing(base_url):',
      '    assert request(base_url, "/api/items/999")[0] == 404',
      '',
      '',
      'def test_create_without_name(base_url):',
      '    assert request(base_url, "/api/items", "POST", {})[0] == 400',
      '',
      '',
      'def test_update(base_url):',
      '    request(base_url, "/api/items", "POST", {"name": "demo"})',
      '    status, item = request(base_url, "/api/items/update", "POST", {"id": 1, "name": "updated"})',
      '    assert status == 200',
      '    assert item["name"] == "updated"',
      '',
      '',
      'def test_update_missing(base_url):',
      '    assert request(base_url, "/api/items/update", "POST", {"id": 999, "name": "x"})[0] == 404',
      '',
      '',
      'def test_delete(base_url):',
      '    request(base_url, "/api/items", "POST", {"name": "demo"})',
      '    assert request(base_url, "/api/items/delete", "POST", {"id": 1})[0] == 200',
      '    assert request(base_url, "/api/items/1")[0] == 404',
      '    assert request(base_url, "/api/items/delete", "POST", {"id": 999})[0] == 404',
    ),
  };
}

export function bootstrapCodeFiles(stack, context = {}) {
  if (stack === 'java') return javaFiles(context);
  if (stack === 'node') return nodeFiles();
  if (stack === 'python') return pythonFiles();
  return {};
}

export function bootstrapTouched(stack, context = {}) {
  const files = bootstrapCodeFiles(stack, context);
  const modify = [];
  if (stack === 'node') modify.push('index.js');
  if (stack === 'python') modify.push('app.py');
  const bootstrap = Object.keys(files).filter((file) => !modify.includes(file));
  return { modify, bootstrap };
}
